const prompt_base = $('Config').first().json.prompt_base;
const image_prompt = $('Start').first().json.image_prompt;

const agg = $('Aggregate').first();
const bin = agg.binary;
const binaryKeys = Object.keys(bin).filter(k => bin[k]);

if (!binaryKeys.length) {
  throw new Error('No se encontraron binarios en Aggregate');
}

// Orden: data, data_1, data_2...
binaryKeys.sort((a, b) => {
  if (a === 'data') return -1;
  if (b === 'data') return 1;
  const na = parseInt(a.split('_')[1] ?? '0', 10);
  const nb = parseInt(b.split('_')[1] ?? '0', 10);
  return na - nb;
});

const parts = [
  {
    text: `${prompt_base}: ${image_prompt}`
  }
];

for (const key of binaryKeys) {
  const mimeType = bin[key].mimeType || 'image/png';

  // ✅ Esto lee el contenido REAL aunque data sea "filesystem-v2"
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  const base64 = buffer.toString('base64');

  parts.push({
    inlineData: {
      mimeType,
      data: base64,
    }
  });
}

return [{
  json: {
    contents: [{ parts }],
    generationConfig: {
      responseModalities: ["TEXT", "IMAGE"],
      imageConfig: {
        aspectRatio: "9:16",
        imageSize: "1K"
      }
    }
  }
}];

// 1. Reunir todos los parts de todos los candidates
const candidates = $('Generate Image - Gemini').first().json.candidates ?? [];
const parts = candidates.flatMap(c => c.content?.parts ?? []);

// 2. Buscar el part que tenga inlineData.data (imagen)
const imagePart = parts.find(p => p.inlineData?.data);

if (!imagePart) {
  throw new Error('Gemini no devolvió ninguna imagen en esta ejecución');
}

// 3. Limpiar el base64 (CRÍTICO)
const base64 = imagePart.inlineData.data
  .replace(/\s/g, '')
  .replace(/^data:image\/\w+;base64,/, '');

// 4. Detectar mimeType (o fallback)
const mimeType = imagePart.inlineData.mimeType || 'image/png';

// 5. Convertir base64 → buffer
const buffer = Buffer.from(base64, 'base64');

// 6. Crear binary para n8n
return [
  {
    json: {
      mimeType: mimeType,
      source: 'gemini'
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        buffer,
        'gemini-image.png',
        mimeType
      ),
    },
  },
];
